/**
 * Huy hiệu: milestone rules evaluated after every rewarding action, grouped by
 * BADGE_GROUPS (tabs). The internal code is generated by the server from the
 * display name and never shown here.
 */
import { el, mount } from '/shared/client.js';
import { confirmAction, drawer, numberField, selectField, statusToggle, table, textAreaField, textField } from '../ui.js';

/** Tab đang chọn, giữ qua các lần vẽ lại trang sau khi lưu. */
let currentGroup = 'all';

function targetHint(ctx) {
  const modules = ctx.meta.modules.map((m) => m.slug).join(', ');
  const features = ctx.meta.features.map((f) => f.code).join(', ');
  return `Để trống nếu không cần. Với "feature_used": mã chức năng (${features}). Với "modules_completed": slug của một mô đun (${modules}).`;
}

export default async function badges(ctx) {
  const rows = await ctx.api.get('/api/admin/badges');
  const rules = ctx.meta.badgeRules;
  const groups = ctx.meta.badgeGroups;
  const groupName = (code) => groups.find((g) => g.code === code)?.name || 'Chưa xếp nhóm';
  if (currentGroup !== 'all' && !groups.some((g) => g.code === currentGroup)) currentGroup = 'all';

  const host = el('div');
  const tabs = el('div.dialogtabs', { role: 'tablist', style: { marginBottom: '16px' } });

  const draw = () => {
    const shown = currentGroup === 'all' ? rows : rows.filter((r) => (r.group_code || 'explore') === currentGroup);
    mount(tabs, [['all', `Tất cả (${rows.length})`], ...groups.map((g) => [g.code, `${g.name} (${rows.filter((r) => (r.group_code || 'explore') === g.code).length})`])]
      .map(([code, label]) => el('button', {
        type: 'button',
        role: 'tab',
        'aria-selected': String(code === currentGroup),
        onclick: () => { currentGroup = code; draw(); },
      }, label)));
    mount(host, table(
      [{ label: '' }, { label: 'Huy hiệu' }, { label: 'Nhóm' }, { label: 'Điều kiện' }, { label: 'Ngưỡng', align: 'right' }, { label: 'Thưởng XP', align: 'right' }, { label: 'Trạng thái' }, { label: '' }],
      shown,
      (row) => el('tr', {}, [
        el('td', { style: { fontSize: 'var(--font-size-display-xs)' } }, row.icon || '🏅'),
        el('td', {}, [
          el('strong', {}, row.name),
          row.description ? el('span.cellmeta', {}, row.description) : null,
        ]),
        el('td', {}, groupName(row.group_code)),
        el('td', {}, [
          rules[row.rule_type] || row.rule_type,
          row.rule_target ? el('span.cellmeta', {}, `Phạm vi: ${row.rule_target}`) : null,
        ]),
        el('td.num', {}, String(row.rule_value)),
        el('td.num', {}, String(row.xp_reward)),
        el('td', {}, [statusToggle(ctx, { entity: 'badges', id: row.id, field: 'is_active', value: row.is_active, name: row.name })]),
        el('td', {}, [el('div.actions', {}, [
          el('button.ekko-btn.ekko-btn--secondary.ekko-btn--sm', { onclick: () => edit(ctx, row, rows) }, 'Sửa'),
          el('button.ekko-btn.ekko-btn--tertiary.ekko-btn--sm', { onclick: () => remove(ctx, row) }, 'Xoá'),
        ])]),
      ]),
    ));
  };
  draw();

  return el('div', {}, [
    el('div.page-head', {}, [
      el('div', {}, [
        el('h1', {}, 'Huy hiệu'),
        el('p', {}, 'Huy hiệu được xét lại sau mỗi hành động có thưởng. Khi người học đạt ngưỡng, huy hiệu được trao ngay và không bao giờ bị thu hồi. Các huy hiệu cùng nhóm và cùng điều kiện hiện trong app thành một chuỗi, ngưỡng thấp trước.'),
      ]),
      el('div.page-head__actions', {}, [
        el('button.ekko-btn.ekko-btn--primary.ekko-btn--md', { onclick: () => edit(ctx, null, rows) }, '+ Thêm huy hiệu'),
      ]),
    ]),

    tabs,
    host,

    el('div.panel', { style: { marginTop: '16px' } }, [
      el('div.panel__head', {}, [el('h2', {}, 'Các loại điều kiện')]),
      el('div.bars', {}, Object.entries(rules).map(([key, label]) => el('div', { style: { display: 'flex', gap: '12px', fontSize: 'var(--font-size-text-sm)' } }, [
        el('code', { style: { minWidth: '170px' } }, key),
        el('span.hint', {}, label),
      ]))),
    ]),
  ]);
}

function edit(ctx, row, rows) {
  const isNew = !row;
  const fields = {
    name: textField({ label: 'Tên hiển thị', value: row?.name, placeholder: 'VD: Streak 14 ngày', required: true }),
    description: textAreaField({ label: 'Mô tả', value: row?.description, rows: 2, placeholder: 'Người học thấy dòng này khi mở huy hiệu.' }),
    icon: textField({ label: 'Biểu tượng', value: row?.icon || '🏅', hint: 'Một emoji, hoặc đường dẫn ảnh bắt đầu bằng /assets/. Huy hiệu là chỗ duy nhất trong app còn dùng emoji.' }),
    group_code: selectField({
      label: 'Nhóm', value: row?.group_code || (currentGroup !== 'all' ? currentGroup : 'learning'),
      options: ctx.meta.badgeGroups.map((g) => [g.code, g.name]),
    }),
    rule_type: selectField({
      label: 'Điều kiện', value: row?.rule_type || 'lessons_completed',
      options: Object.entries(ctx.meta.badgeRules).map(([key, label]) => [key, `${key} — ${label}`]),
    }),
    rule_value: numberField({ label: 'Ngưỡng', value: row?.rule_value ?? 1, required: true }),
    rule_target: textField({ label: 'Phạm vi (tuỳ chọn)', value: row?.rule_target, hint: targetHint(ctx) }),
    xp_reward: numberField({ label: 'Thưởng XP khi nhận', value: row?.xp_reward ?? 0 }),
    order_index: numberField({ label: 'Thứ tự hiển thị', value: row?.order_index ?? (Math.max(0, ...rows.map((r) => r.order_index)) + 1) }),
  };

  drawer({
    title: isNew ? 'Thêm huy hiệu' : `Sửa: ${row.name}`,
    fields: Object.values(fields),
    onSave: async () => {
      // Mã huy hiệu không hiện ở đây: huy hiệu mới thì server tự sinh từ tên, huy hiệu cũ giữ mã đang dùng.
      const body = Object.fromEntries(Object.entries(fields).map(([key, field]) => [key, field.get()]));
      body.rule_target = body.rule_target ? String(body.rule_target).trim() : null;
      try {
        if (isNew) await ctx.api.post('/api/admin/badges', body);
        else await ctx.api.patch(`/api/admin/badges/${row.id}`, body);
        ctx.notify('Đã lưu huy hiệu', 'success');
        await ctx.reload();
      } catch (err) {
        ctx.notify(err.message, 'error');
        return false;
      }
      return true;
    },
  });
}

async function remove(ctx, row) {
  if (!await confirmAction(`Xoá huy hiệu "${row.name}"? Những người đã nhận sẽ mất huy hiệu này khỏi bộ sưu tập.`)) return;
  try {
    await ctx.api.delete(`/api/admin/badges/${row.id}`);
    ctx.notify('Đã xoá huy hiệu');
    await ctx.reload();
  } catch (err) {
    ctx.notify(err.message, 'error');
  }
}
